#define main legacy_main
#include "../knn-cuda/main.cu"
#undef main
#include <vector>
#include <string>
#include <algorithm>
struct F{int n,q,d,k;std::vector<float>a,b,out,gold;std::vector<int>ix,gi;std::vector<double>gd;F(int f){n=f==1?129:65;q=f==1?67:37;d=f==1?68:5;k=f==1?20:7;a.resize(n*d);b.resize(q*d);out.resize(q*k);gold.resize(q*k);ix.resize(q*k);gi.resize(q*k);gd.resize(q*k);if(f==1){srand(2);for(auto*v:{&a,&b})for(float&z:*v)z=float(rand())/float(RAND_MAX);}else{for(int z=0;z<d;z++){for(int i=0;i<n;i++)a[z*n+i]=float(((i%13)*3+z*5)%17)/8-.5f;for(int i=0;i<q;i++)b[z*q+i]=float(((i%11)*7+z*3)%19)/8-.5f;}}if(!knn_c(a.data(),n,b.data(),q,d,k,gold.data(),gi.data()))abort();for(int j=0;j<q;j++){std::vector<std::pair<double,int>>v;for(int i=0;i<n;i++){double s=0;for(int z=0;z<d;z++){double t=double(a[z*n+i])-b[z*q+j];s+=t*t;}v.emplace_back(s,i);}std::sort(v.begin(),v.end());for(int t=0;t<k;t++){gd[t*q+j]=sqrt(v[t].first);if(gi[t*q+j]!=v[t].second)abort();}}}void call(){knn_parallel(a.data(),n,b.data(),q,d,k,out.data(),ix.data());}};
int main(int argc,char**argv){int rep=argc>1?atoi(argv[1]):10;std::vector<F>fs;std::vector<double>prefix;for(int f=1;f<=2;f++){fs.emplace_back(f);auto&z=fs.back();prefix.insert(prefix.end(),{double(z.n),double(z.q),double(z.d),double(z.k)});prefix.insert(prefix.end(),z.a.begin(),z.a.end());prefix.insert(prefix.end(),z.b.begin(),z.b.end());z.call();}cudaDeviceSynchronize();for(int trial=1;trial<=5;trial++){cudaDeviceSynchronize();auto st=std::chrono::steady_clock::now();for(int z=0;z<rep;z++)for(auto&f:fs)f.call();cudaDeviceSynchronize();double elapsed=std::chrono::duration<double>(std::chrono::steady_clock::now()-st).count()/rep;std::vector<double>got;double err=0;bool ok=cudaGetLastError()==cudaSuccess;for(auto&f:fs){for(size_t i=0;i<f.out.size();i++){err=std::max(err,fabs(double(f.out[i])-f.gd[i]));ok&=std::isfinite(f.out[i])&&fabs(f.out[i]-f.gold[i])<=1e-3&&f.ix[i]==f.gi[i];}got.insert(got.end(),f.out.begin(),f.out.end());got.insert(got.end(),f.ix.begin(),f.ix.end());}ok&=err<=1e-3;auto art=prefix;art.insert(art.end(),got.begin(),got.end());const char*dir=getenv("STUDY_OUTPUT_DIR");std::string path=std::string(dir?dir:".")+"/output_trial"+std::to_string(trial)+".bin";FILE*fp=fopen(path.c_str(),"wb");fwrite(art.data(),8,art.size(),fp);fclose(fp);printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.17g,\"correct\":%s,\"checked_values\":%zu,\"max_abs_error\":%.17g,\"max_rel_error\":0.0,\"timing_region\":\"two_complete_KNN_hostinclusive_alloc_H2D_3kernels_D2H_free\",\"jit_excluded\":true,\"internal_repeats\":%d,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"float64\",\"count\":%zu,\"byte_order\":\"little\"}}\n",trial,elapsed,ok?"true":"false",got.size(),err,rep,path.c_str(),art.size());if(!ok)return 2;}}
